export const HOWTO = [
  // ── Emergency & stop work ────────────────────────────────────────────────
  { id: 'emergency-now', topic: 'emergency', critical: true, q: 'There is an emergency right now. What do I do?', a: 'STOP WORK. Do not use this portal first.\n\n1. Make the area safe only if you can do it without putting yourself at risk.\n2. Call 911 or your site emergency number / radio channel right now. On a pad, follow the site emergency response plan and muster.\n3. Notify your supervisor.\n4. Care for the injured within your training. Do not move a seriously injured person unless they are in immediate danger.\n\nOnly when everyone is safe: file the Incident Report (same shift).', k: 'emergency help 911 hurt injured accident fire explosion gas leak h2s man down call', links: [L.incident] },
  { id: 'stop-work-authority', topic: 'emergency', q: 'Can I stop the job?', a: 'Yes. Every person on the job has Stop Work Authority and the obligation to use it. If something is unsafe or you are unsure, stop the job, make it safe, and talk it through. Nobody gets in trouble for a good-faith stop.\n\nAfterwards, capture it: a STOP & Take 5 or a Good Catch / Near Miss. If something needs fixing, put it on the SAIL log so it has an owner and a due date.', k: 'stop work authority swa stop the job refuse unsafe work shut it down', links: [L.stop5, L.goodCatch, L.sailEntry] },
  { id: 'h2s', topic: 'emergency', critical: true, q: 'My H2S / gas monitor is alarming', a: 'STOP WORK and get out. Move upwind / crosswind to your muster point, alert others, and call it in on the radio or to your site emergency number. Do not go back in to rescue someone without the right breathing protection and training: most H2S fatalities are rescuers.\n\nReport it on the Incident Report once everyone is safe.', k: 'h2s hydrogen sulfide gas alarm monitor alarming lel sour gas toxic gas evacuate muster upwind', links: [L.incident] },
  { id: 'spill-now', topic: 'emergency', critical: true, q: 'There is a spill or release', a: 'Stop the source only if it is safe to do so. Keep people away, eliminate ignition sources, and contain it with the spill kit if you are trained. Notify your supervisor right away: many spills have legal reporting deadlines (ADEC, the operator, sometimes the National Response Center).\n\nThen report it on the Incident Report and mark that an environmental release occurred.', k: 'spill release leak oil spill fuel spill diesel glycol produced water containment adec reportable', links: [L.incident] },
  { id: 'injury-now', topic: 'emergency', critical: true, q: 'Someone got hurt', a: 'Take care of the person first. Call 911 / the site emergency number for anything beyond basic first aid. Notify your supervisor immediately.\n\nThen, same shift, fill out the Incident Report. Witnesses fill out a Witness Statement. Do not decide on your own whether it is "recordable": report it and the safety team classifies it.', k: 'injury injured hurt cut bleeding broken bone sprain burn first aid medical treatment someone got hurt', links: [L.incident, L.witness] },
  { id: 'vehicle-accident', topic: 'emergency', q: 'I was in a vehicle accident', a: 'Make the scene safe (hazards on, out of traffic if you can), check for injuries and call 911 if anyone is hurt. Notify your supervisor. Take photos if it is safe.\n\nThen fill out the Incident Report (it has vehicle sections) and, if equipment or property was damaged, the Property Damage Report.', k: 'vehicle accident car wreck crash rollover hit truck backed into collision ditch', links: [L.incident, L.propDamage] },

  // ── Getting started ──────────────────────────────────────────────────────
  { id: 'what-is', topic: 'start', q: 'What is the SLP Safety Portal?', a: 'It is where you do your safety paperwork from your phone, tablet or computer: THAs, BBS cards, inspections, permits, audits, near misses and incident reports, plus your online training (LMS).\n\nEverything you submit feeds the safety picture, so we can see the biggest risks and fix them before someone gets hurt. AnthroSafe™ Field Driven Safety.', k: 'what is this portal about anthrosafe overview what does it do' },
  { id: 'need-login', topic: 'start', q: 'Do I need an account or password to fill out forms?', a: 'No. Field forms (THA, BBS, inspections, permits, audits, near misses, incident reports) do not need a login. Open the form and go.\n\nYou only sign in for: online training (LMS, email + password), and management pages like SAIL management, corrective actions and the investigation dashboard (an emailed sign-in link, no password).', k: 'login account password sign in username do i need register' },
  { id: 'find-form', topic: 'start', q: 'How do I find a form?', a: 'On the home page either type in the search box (for example "sling" or "hot work") or tap a folder to open it. The Quick Start buttons at the top go straight to the most-used forms.\n\nYou can also type the form name here in the Help Desk and tap the button in the answer.', k: 'find form where is search folder locate missing form', links: [L.home] },
  { id: 'add-home-screen', topic: 'start', q: 'How do I put the portal on my phone home screen?', a: 'iPhone (Safari): open portal.slpalaska.com, tap the Share button, then "Add to Home Screen".\n\nAndroid (Chrome): open portal.slpalaska.com, tap the ⋮ menu, then "Add to Home screen" or "Install app".\n\nIt then opens like an app with one tap.', k: 'home screen icon app install shortcut bookmark phone iphone android add to home', links: [L.home] },
  { id: 'which-device', topic: 'start', q: 'Can I use my phone, tablet or computer?', a: 'Yes. Any of them, in any modern browser (Chrome, Safari, Edge). The forms are built for a phone in the field. Keep the browser up to date.', k: 'phone tablet ipad computer laptop browser device chrome safari edge supported' },
  { id: 'quick-start', topic: 'start', q: 'What are the Quick Start buttons?', a: 'They are one-tap shortcuts to the forms people use most, ranked by how often they were actually submitted in the last 90 days, plus Incident Report and Good Catch which are always there.', k: 'quick start shortcuts most used popular top forms buttons', links: [L.home] },
  { id: 'who-sees', topic: 'start', q: 'Who can see what I submit?', a: 'SLP Alaska safety staff and the authorized people at your company. Investigation details are restricted to assigned investigators. Clients see their own company\u2019s data only.\n\nBe honest and factual. The point is fixing problems, not blaming people.', k: 'who sees privacy confidential my data visible manager boss see', links: [] },
  { id: 'anonymous', topic: 'start', q: 'Can I report something anonymously?', a: 'Most forms ask for your name because follow-up questions need someone to ask. Surveys are anonymous unless you choose to add your name. If you are worried about reporting something, talk to SLP Alaska directly at ' + SLP_PHONE + '. Retaliation for reporting a safety concern is against the law (OSHA Section 11(c)).', k: 'anonymous anonymously name retaliation fear afraid whistleblower confidential report', links: [L.phone] },
  { id: 'spanish', topic: 'start', q: 'Is the portal in Spanish?', a: 'Not yet. The forms are in English today. If language is a barrier for you or your crew, tell your supervisor or SLP Alaska so we can help.', k: 'spanish espanol español language translate translation idioma' },

  // ── Filling out & submitting ─────────────────────────────────────────────
  { id: 'how-submit', topic: 'submit', q: 'How do I submit a form?', a: 'Fill in the required fields (marked with a red *), then tap the Submit button at the bottom. Wait for the green success screen. That screen is your proof it went in.\n\nIf you get a pop-up telling you what is missing, answer that question and tap Submit again.', k: 'submit send save turn in finish done button complete' },
  { id: 'did-it-go', topic: 'submit', q: 'How do I know my form went through?', a: 'You get a green "Submitted Successfully" (or "Permit Issued", "THA Created") screen. If you did not see it, it did not go in. Do not close the page; tap Submit again or read the message on screen.\n\nIf the message says your data was saved on the device or offline, see "My form says it was saved on my device".', k: 'did it go through confirm confirmation received success went through submitted check' },
  { id: 'required-field', topic: 'submit', q: 'It will not let me submit / says a field is required', a: 'A required answer is missing. Look for fields with a red * and any pop-up message (for example "Please select an Observation Type"). Scroll up: the missing one is often above where you are.\n\nTHA / JSA has one more rule: you must run the quality check and score 60% (D) or better before Submit works.', k: 'required field cannot submit will not submit missing field red asterisk error please answer greyed out button not working' },
  { id: 'edit-after', topic: 'submit', q: 'I made a mistake after I submitted. Can I edit it?', a: 'Field forms cannot be edited after submitting. That protects the record. Submit a corrected form and note "correction to earlier submission" in the comments, or tell your supervisor / SLP Alaska what needs fixing.\n\nOpen THAs are different: you can add crew and steps from "My Open THAs" with the THA code until you close it out.', k: 'edit mistake wrong change fix after submit correct typo delete submission undo' },
  { id: 'delete', topic: 'submit', q: 'Can I delete something I submitted?', a: 'No. Submitted records are not deleted by field users. That is what makes them hold up later. If something was submitted by mistake, tell SLP Alaska and it will be handled.', k: 'delete remove erase submission duplicate by mistake' },
  { id: 'photos', topic: 'submit', q: 'How do I add photos?', a: 'Forms with a photo section let you take a picture or pick one from your phone. Most allow up to 6 photos and shrink them automatically so they upload on slow signal.\n\nIf photos fail to upload, the form data still saves and SLP is notified.', k: 'photo photos picture pictures camera image upload attach video' },
  { id: 'photo-fail', topic: 'submit', q: 'My photos will not upload', a: 'Weak signal is the usual cause. The form still saves without the photos and you are told so. Try fewer photos, move to better signal, or submit again from Wi-Fi. If your phone asks for camera / photo permission, allow it for your browser.', k: 'photo upload failed fail error slow camera permission picture not uploading' },
  { id: 'print', topic: 'submit', q: 'Can I print a form or get a copy?', a: 'THA / JSA, Critical Lift Plan, Fall Protection Plan and the Dropped Object Energy Assessment have a Print button. For other forms, take a screenshot of the green success screen. In the print dialog you can choose "Save as PDF" for a copy. Clients can download their data from the Client Data Export Portal.', k: 'print printout copy pdf save copy paper hard copy', links: [] },
  { id: 'date-time', topic: 'submit', q: 'The date or time is wrong on the form', a: 'Dates fill in from your device. Check that your phone\'s date, time and time zone are set to automatic (Alaska time). You can change the date field yourself before submitting.', k: 'date time wrong timezone time zone clock' },
  { id: 'company-location-missing', topic: 'submit', q: 'My company or location is not in the list', a: 'Pick the closest match and write the correct one in the comments, then tell your supervisor or SLP Alaska so the list gets updated. Some forms have an "Other" option.', k: 'company not listed location not listed missing dropdown pad not in list add location' },
  { id: 'duplicate-warning', topic: 'submit', q: 'It says this item was already inspected in the last 30 days', a: 'That is a helpful warning, not an error. Someone already logged a monthly inspection of that item ID in the past 30 days. Check the ID is right. If you are re-inspecting on purpose (damage, before use, new month), continue.', k: 'already inspected 30 days duplicate warning recent inspection' },

  // ── Offline ──────────────────────────────────────────────────────────────
  { id: 'offline-forms', topic: 'offline', q: 'Can I fill out forms with no signal?', a: 'Get signal before you submit whenever you can. Many forms (BBS, Stop & Take 5, Hazard ID, most monthly inspections and many audits) have SafeSubmit: if the send fails they keep your answers on the phone instead of losing them, and tell you so.\n\nPermits and THAs need signal to issue, because they create a code you need later.\n\nThis Help Desk works without signal once it has been opened on your phone.', k: 'offline no signal no service no internet no connection dead zone wifi cell service remote' },
  { id: 'saved-on-device', topic: 'offline', q: 'My form says it was saved on my device / offline', a: 'Your answers are stored in this browser on this phone. Do not clear browser data, do not use private / incognito mode, and do not switch phones.\n\nTell your supervisor or SLP Alaska (' + SLP_PHONE + ') the form name and time so it can be recovered. SLP is alerted automatically when this happens.', k: 'saved on device saved locally offline queue auto submit reconnect stored on phone pending', links: [L.phone] },
  { id: 'help-offline', topic: 'offline', q: 'Does the Help Desk work offline?', a: 'Yes. All the answers live on your phone, so searching never needs signal. Open the Help Desk once while you have signal and it will open again later with none.', k: 'help offline help desk without signal' },
  { id: 'slow', topic: 'offline', q: 'The portal is slow', a: 'Usually weak signal. Try: move to better signal or Wi-Fi, close other apps, refresh the page. Submit buttons retry on their own if the connection drops for a moment. Do not tap Submit over and over; wait for the result.', k: 'slow loading spinning takes forever lag lte starlink' },

  // ── Permits, THA & codes ─────────────────────────────────────────────────
  { id: 'tha-how', topic: 'permits', module: 'daily-forms', q: 'How do I do a THA / JSA?', a: '1. Open THA / JSA and tap "New THA".\n2. Fill in the task, location, crew lead, hazards, PPE and permits.\n3. Add task steps: each step, its hazards, and the controls.\n4. Tap the quality check. You need 60% (D) or better. Physical controls (barricade, lock, isolate, spotter, verify) score higher than "be aware".\n5. Submit. Write down the THA CODE or take a photo of the screen.\n6. Crew members sign on from "My Open THAs".\n7. At end of shift, "Close Out THA" with the code: what went well, what did not, how to improve.', k: 'tha jsa how to fill out task hazard analysis job safety analysis steps controls crew sign on', links: [L.tha] },
  { id: 'tha-score', topic: 'permits', module: 'daily-forms', q: 'Why is my THA score low?', a: 'The quality check rewards: at least 3 to 5 steps, a hazard on every step, and real controls. Words like barricade, lock, tag, isolate, guardrail, harness, spotter, verify, test, secure and communicate count as controls. "Be careful" or "stay aware" alone does not, and costs points.\n\nAdd detail to each step and name the physical control.', k: 'tha score low grade quality check fail f d awareness controls improve', links: [L.tha] },
  { id: 'tha-code', topic: 'permits', module: 'daily-forms', q: 'What is the THA code and where do I find it?', a: 'When the THA is created the screen shows a THA CODE. It is the key to add crew or close the THA out, so nobody else can close your THA. Write it on the THA or take a photo of the screen.\n\nLost it? Ask your crew lead (it is on their screen photo) or create a new THA for the rest of the shift and tell your supervisor.', k: 'tha code lost forgot code close out code where key', links: [L.tha] },
  { id: 'tha-join', topic: 'permits', module: 'daily-forms', q: 'How do I sign onto my crew\'s THA?', a: 'Open THA / JSA, tap "My Open THAs", pick your crew\'s THA, read it, then add yourself to the crew. Ask the crew lead for the THA code if it asks for it.', k: 'sign on join crew tha add crew member sign onto acknowledge', links: [L.tha] },
  { id: 'tha-close', topic: 'permits', module: 'daily-forms', q: 'How do I close out a THA at end of shift?', a: 'Open THA / JSA, tap "Close Out THA", enter the THA number and THA code, your name, and answer the three questions (what went well, what did not go as planned, how we will improve). Then close it.', k: 'close out tha end of shift close tha finish', links: [L.tha] },
  { id: 'permit-how', topic: 'permits', module: 'permits', q: 'How do I issue a permit?', a: 'Open the permit (Hot Work, Confined Space, LOTO, Excavation, Energized Electrical, Opening & Blinding or Unit Work) from the Permits folder, stay on "New Permit", fill it in and submit. The success screen shows the permit number and a CLOSE-OUT CODE. Write the code on the printed permit or take a photo.', k: 'issue permit new permit create permit how permit', links: [L.hotWork, L.cse, L.loto] },
  { id: 'permit-close', topic: 'permits', module: 'permits', q: 'How do I close out a permit?', a: 'Open the same permit form, tap "Close Out Permit", pick your permit from the open list, tick the close-out checklist, enter the close-out code from the permit receipt plus the required names and time, then tap Close Out.', k: 'close permit close out permit closeout finish permit end permit', links: [L.hotWork] },
  { id: 'permit-code-lost', topic: 'permits', module: 'permits', q: 'I lost the permit close-out code', a: 'The code is only shown on the screen when the permit is issued (and on any printout or photo). Check with the permit issuer. If nobody has it, contact SLP Alaska with the permit number. Codes are not shown in lists on purpose: they stop someone else closing your permit.', k: 'lost close out code forgot permit code cannot close permit', links: [L.phone] },
  { id: 'permit-not-listed', topic: 'permits', module: 'permits', q: 'My permit is not in the open permit list', a: 'The list only shows permits of that type that are still open. Make sure you are in the right permit form (a hot work permit only appears under Hot Work). If it was already closed, it will not show.', k: 'permit not in list missing open permit cannot find permit' },
  { id: 'loto-workers', topic: 'permits', module: 'permits', q: 'How do workers sign on and off an LOTO permit?', a: 'Open Energy Isolation / LOTO. Each worker adds their name and lock to the worker log on the permit and signs out when their lock comes off. The permit can only be closed once all workers have signed out and locks are removed.', k: 'loto sign on sign off worker log personal lock lockout', links: [L.loto] },
  { id: 'gas-limits', topic: 'permits', q: 'What are acceptable gas test readings?', a: 'The hot work permit lists: O₂ 19.5 to 23.5%, LEL under 10%, H₂S under 10 ppm, CO under 25 ppm. Follow your site and operator limits if they are stricter. Out of range = no work until it is fixed and re-tested.', k: 'gas test readings limits o2 oxygen lel h2s co ppm acceptable atmosphere monitor' },
  { id: 'fire-watch', topic: 'permits', q: 'How long does fire watch last?', a: 'At least 30 minutes after hot work ends (longer if your site requires it). The hot work close-out asks you to confirm it.', k: 'fire watch how long 30 minutes hot work' },

  // ── Reporting ────────────────────────────────────────────────────────────
  { id: 'which-report', topic: 'report', q: 'Which form do I use to report something?', a: '• Someone hurt or sick, a spill, vehicle accident, fire, process safety event, security event: Incident Report.\n• Something almost happened: Good Catch / Near Miss.\n• A hazard that is still there: Hazard ID Report (and SAIL it if someone needs to fix it).\n• Only equipment or property damaged: Property Damage Report.\n• You saw an incident happen: Witness Statement.\n• You watched someone work: BBS Observation.', k: 'which form report what form to use near miss vs incident hazard report difference', links: [L.incident, L.goodCatch, L.hazard, L.propDamage, L.witness, L.bbs] },
  { id: 'incident-how', topic: 'report', module: 'incidents', q: 'How do I fill out an Incident Report?', a: 'Open Incident Report. Tell what happened in plain words, where and when, who was involved, injuries (body part, nature of injury), damage, any release, and what controls were in place. Add photos and witnesses.\n\nNot finished? Tap Save Draft and finish later. When you tap Submit, the SLP team gets an email copy right away.', k: 'incident report how fill out report injury report accident report form', links: [L.incident] },
  { id: 'incident-when', topic: 'report', module: 'incidents', q: 'How soon do I have to report an incident?', a: 'Tell your supervisor immediately and submit the Incident Report the same shift. OSHA deadlines for the employer are short: a fatality within 8 hours, an in-patient hospitalization, amputation or loss of an eye within 24 hours. Late reports make that impossible.', k: 'how soon deadline when report incident time limit 8 hours 24 hours late report' },
  { id: 'incident-draft', topic: 'report', module: 'incidents', q: 'Can I save an incident report and finish it later?', a: 'Yes. Tap Save Draft (you need at least your name or a short description). Your draft ID is shown. Finish it later and tap Submit. Only a submitted report notifies the SLP team.', k: 'save draft incident later finish later draft id', links: [L.incident] },
  { id: 'after-incident', topic: 'report', module: 'incidents', q: 'What happens after I submit an incident report?', a: 'The SLP team is emailed a copy right away. The incident is triaged, and if it needs one an investigator is assigned. You may be asked for a witness statement or an interview. Corrective actions come out of the investigation with owners and due dates.', k: 'what happens next after incident report investigation follow up triage' },
  { id: 'near-miss-worth', topic: 'report', q: 'Is it worth reporting a near miss?', a: 'Yes. Every near miss is a free lesson: the same causes that almost hurt someone today will hurt someone later if nothing changes. Near misses and good catches are leading indicators: they show us the risk before the injury.', k: 'near miss worth it why report near miss good catch pointless', links: [L.goodCatch] },
  { id: 'witness-how', topic: 'report', module: 'incidents', q: 'How do I write a witness statement?', a: 'Open Witness Statement. Write only what you saw, heard and did, in order, in your own words. No guessing about why, no blame. Write it as soon as you can, before you talk it over with others.', k: 'witness statement how write what to write', links: [L.witness] },
  { id: 'recordable', topic: 'report', q: 'Is my injury recordable? What is first aid?', a: 'You do not decide that in the field: report it and the safety team classifies it under OSHA 29 CFR 1904.\n\nFor background: first aid (1904.7(b)(5)(ii)) is a closed list, such as non-prescription meds at non-prescription strength, bandages / butterfly strips, hot or cold packs, cleaning a wound, removing a splinter, eye flushing, finger guards, non-rigid support (wraps), drinking fluids for heat stress. Treatment beyond that list (stitches, prescription meds, rigid splints), days away, restricted work or job transfer, loss of consciousness, or a significant diagnosed injury makes it recordable.', k: 'recordable first aid osha 1904 log 300 classification medical treatment beyond first aid restricted days away dart trir' },

  // ── SAIL ─────────────────────────────────────────────────────────────────
  { id: 'sail-what', topic: 'sail', module: 'sail', q: 'What is the SAIL log?', a: 'SAIL = Safety Action Item List. It is where every "someone needs to fix this" goes, so each item has an owner, a priority and a due date, and nothing gets forgotten.\n\nPriorities: A - Critical, B - Moderate, C - Best Practice.', k: 'sail what is sail log safety action item list meaning', links: [L.sailEntry] },
  { id: 'sail-add', topic: 'sail', module: 'sail', q: 'How do I add or assign an action item on the SAIL log?', a: 'Open SAIL Log Entry. Enter your name, company, location, the action item and why, who it is assigned to and their email, priority, and the target completion date. Submit. The assignee gets an email.\n\nBBS and LSR audit forms also have an "Add to SAIL Log" button so you can send a finding straight over.', k: 'add sail item new action item assign task create sail', links: [L.sailEntry] },
  { id: 'sail-mine', topic: 'sail', module: 'sail', q: 'How do I see and close my SAIL items?', a: 'Open SAIL Log Management. Enter your email to get a sign-in link (no password), open the link on the same device, and you are in. Pick the item, add an update narrative and the resolution notes, set the status to Closed when it is done.\n\nOnly closing an item finishes it. Comments alone leave it open.', k: 'my sail items close sail update sail item view assigned sail log management overdue', links: [L.sailMgmt] },
  { id: 'sail-email', topic: 'sail', module: 'sail', q: 'I got an email saying I was assigned an action item', a: 'Someone put an item on the SAIL log with your name on it. Open SAIL Log Management (sign in with the emailed link), find the item, do the work, add your notes and close it by the target date. If it is not yours, reply to whoever assigned it or tell your supervisor so it can be reassigned.', k: 'assigned email action item email notification sail assigned to me', links: [L.sailMgmt] },
  { id: 'sail-overdue', topic: 'sail', module: 'sail', q: 'What happens if my action item is overdue?', a: 'It shows as overdue on the SAIL and predictive safety dashboards that management reviews. An open item with a passed due date is exactly what an auditor, a client or a court looks for. Close it, or ask the person who assigned it for a new date with a reason, in writing.', k: 'overdue late past due missed due date what happens extension' },
  { id: 'ca-mine', topic: 'sail', module: 'incidents', q: 'How do I update a corrective action from an investigation?', a: 'Open Corrective Actions, sign in with the emailed link, then enter your email to see the actions assigned to you. Open one, add what you did, and mark it complete when it is actually done.', k: 'corrective action update close investigation action my corrective actions capa', links: [L.ca] },

  // ── Inspections ──────────────────────────────────────────────────────────
  { id: 'inspect-fail', topic: 'inspect', q: 'The item failed inspection. What now?', a: 'Take it out of service now: tag it "DO NOT USE" and remove it from the work area so nobody grabs it. Record the failure on the inspection form with a photo. Tell your supervisor. If it needs repair or replacement by someone, put it on the SAIL log.', k: 'failed inspection fail out of service tag out damaged defect remove from service red tag', links: [L.sailEntry] },
  { id: 'inspect-monthly', topic: 'inspect', module: 'inspections', q: 'Which inspections are monthly?', a: 'The Monthly Inspections folder: beam clamp, chain hoist, emergency drill, eyewash, harness, fire extinguisher, first aid kit, ladder, lanyard / SRL, AED, plate clamp, shackle, synthetic sling and wire rope. Rigging and fall protection gear also gets inspected by the user before every use.', k: 'monthly inspections which list schedule how often frequency', links: [L.home] },
  { id: 'inspect-preshift', topic: 'inspect', module: 'inspections', q: 'Where are the pre-shift equipment inspections?', a: 'Home page, Equipment Inspections folder: Heavy Equipment (daily), Crane (pre-shift), Forklift (pre-shift) and Vehicle (pre-trip).', k: 'pre shift pre trip daily equipment inspection forklift crane vehicle heavy equipment', links: [['Vehicle Inspection', '/vehicle-inspection'], ['Forklift Inspection', '/forklift-inspection'], ['Crane Inspection', '/crane-inspection'], ['Heavy Equipment', '/heavy-equipment-inspection']] },
  { id: 'inspect-id', topic: 'inspect', q: 'What ID do I put for the equipment?', a: 'Use the ID / serial / asset number on the item\'s tag. Use the same ID every month so the history lines up. No tag on a sling or shackle? It should not be in service: tag it out and report it.', k: 'equipment id serial number asset number tag id which id' },
  { id: 'sling-reject', topic: 'inspect', module: 'inspections', q: 'When do I throw away a synthetic sling?', a: 'Remove it from service for: missing or unreadable tag, cuts, tears, holes, burns, melting or charring, chemical damage, red core yarns / warning threads showing, broken or worn stitching, knots, damaged fittings, or anything else that makes you doubt it (ASME B30.9).', k: 'sling reject discard throw away remove from service criteria web sling round sling' },
  { id: 'extinguisher-how', topic: 'inspect', module: 'inspections', q: 'What do I check on a fire extinguisher?', a: 'Monthly: in its place and unobstructed, gauge in the green, pin and tamper seal intact, no damage, corrosion or leaks, hose and nozzle OK, label readable, and the inspection tag current. Record it on the Fire Extinguisher Inspection with the extinguisher ID.', k: 'fire extinguisher check monthly what to look for gauge green pin seal', links: [['Fire Extinguisher Inspection', '/fire-extinguisher-inspection']] },
  { id: 'harness-check', topic: 'inspect', module: 'inspections', q: 'What do I check on a harness?', a: 'Webbing: cuts, burns, fraying, chemical damage, UV fade. Stitching: broken or pulled. Hardware: D-rings and buckles not bent, cracked or corroded; working tongues. Labels readable. Fall indicator not deployed. Any doubt = out of service.', k: 'harness check inspect what to look for webbing d ring' },

  // ── LMS ──────────────────────────────────────────────────────────────────
  { id: 'lms-login', topic: 'lms', module: 'lms', q: 'How do I sign in to online training?', a: 'Tap "Online Training Portal (LMS)" (or Quick Start → Training). Sign in with the email and password your administrator set up. The first time, you will be asked to set your own password.', k: 'lms login sign in training log in online training how', links: [L.lms] },
  { id: 'lms-forgot', topic: 'lms', module: 'lms', q: 'I forgot my training password', a: 'There is no self-service reset link yet. Ask your company training administrator or SLP Alaska to reset it; you will get a temporary password and be asked to choose a new one when you sign in.', k: 'forgot password reset password locked out cannot log in lms password wrong password', links: [L.phone] },
  { id: 'lms-no-account', topic: 'lms', module: 'lms', q: 'I do not have a training account', a: 'Accounts are created by your company training administrator or SLP Alaska. Ask them to add you with your email address.', k: 'no account need account sign up register create account lms new employee' },
  { id: 'lms-courses', topic: 'lms', module: 'lms', q: 'Where are my courses?', a: 'After you sign in you land on My Training Dashboard with your assigned courses. Tap a course to start or continue it. No courses showing? Your administrator has not assigned any yet. Ask them.', k: 'my courses where training assigned courses not showing missing course', links: [L.lmsDash] },
  { id: 'lms-pass', topic: 'lms', module: 'lms', q: 'What score do I need to pass a course quiz?', a: 'Each course sets its passing score; 80% is the usual default. It is shown at the top of the quiz. Didn\'t pass? Review the slides and tap Retake Quiz.', k: 'pass score passing grade quiz test 80 percent retake fail failed quiz', links: [L.lmsDash] },
  { id: 'lms-cert', topic: 'lms', module: 'lms', q: 'How do I get my training certificate?', a: 'When you pass a course a certificate is created. Open it from your Training Dashboard. Each certificate has its own link you can show or send to a supervisor or client.', k: 'certificate cert proof of training card download print certificate completion', links: [L.lmsDash] },
  { id: 'lms-audio', topic: 'lms', module: 'lms', q: 'The course audio or video will not play', a: 'Turn your volume up and the silent switch off (iPhone). Tap play once yourself: browsers block auto-play. Try Wi-Fi or better signal, then refresh. The Transcript button shows the narration as text.', k: 'audio video sound not playing no sound narration will not play stuck loading slide' },
  { id: 'lms-stuck', topic: 'lms', module: 'lms', q: 'My course progress did not save / I am stuck', a: 'Refresh the page and go back in from the dashboard. Make sure you stayed signed in. If a course still will not finish, tell your training administrator the course name and where it stops.', k: 'progress not saved stuck course frozen will not finish next button' },
  { id: 'lms-reminders', topic: 'lms', module: 'lms', q: 'Why am I getting training reminder emails?', a: 'You have assigned or required courses that are not complete or are due for a refresher. The weekly reminder lists them. Finish them and the reminders stop.', k: 'reminder emails training reminder why emails weekly email due refresher expired' },
  { id: 'lms-refresher', topic: 'lms', module: 'lms', q: 'When does my training expire?', a: 'Courses with a refresher frequency come due again after that period (for example yearly). Your dashboard and the weekly reminder show what is due.', k: 'expire expiration refresher annual renewal due again how long valid' },
  { id: 'lms-online-enough', topic: 'lms', q: 'Does an online course qualify me to run equipment?', a: 'No. For forklifts, cranes, aerial lifts, loaders and excavators the online course is the knowledge part. You also need a hands-on practical evaluation by a qualified evaluator (the Practical Evaluation forms) before operating on your own.', k: 'qualified operator certified online enough practical required forklift certification card', links: [['Forklift Practical', '/forklift-practical']] },
  { id: 'competency', topic: 'lms', module: 'lms-competency', q: 'What is a competency program?', a: 'A competency program in the LMS goes beyond a quiz: units, practice and real-world scenarios, with results your supervisor can see. Open it from your training dashboard when one is assigned.', k: 'competency program scenario practice units skills', links: [L.lmsDash] },
  { id: 'company-admin-add', topic: 'lms', module: 'lms', q: 'I am a training admin. How do I add an employee or assign courses?', a: 'Open Training Administration (from your Training Dashboard → Company Dashboard / admin). Use "+ Add Employee" for new people (they start with a temporary password and must set their own) and "+ Assign Courses" for individual assignments on top of company-required courses. The Training Matrix shows who is complete.', k: 'add employee assign course training admin company admin matrix crew deactivate', links: [L.companyAdmin] },

  // ── Investigations ───────────────────────────────────────────────────────
  { id: 'inv-who', topic: 'investigate', module: 'incidents', q: 'Who can use the investigation tools?', a: 'Only people given access by SLP Alaska. The dashboard and management pages need an emailed sign-in link for an address on the access list. The Investigation Workbench also needs the investigator role on the account. Everyone else can still report incidents and witness statements.', k: 'investigation access who can investigate permission investigator role not allowed', links: [L.invDash] },
  { id: 'inv-stages', topic: 'investigate', module: 'incidents', q: 'How does the Investigation Workbench work?', a: 'Four stages:\n1. Setup & Evidence: confirm scope, photos, witnesses.\n2. What Happened: the timeline, with critical events marked.\n3. Why It Happened: Local Review, 5-Why or full RCA depending on severity; root causes and contributing factors.\n4. Close It Out: corrective actions using the hierarchy of controls, lessons learned, approval, and the PDF.\n\nStatus moves Submitted → Triage → First Draft → Asset Review → Final Review → Pending Approval → Approved → Closed.', k: 'workbench stages how investigation works steps status rca 5 why', links: [L.workbench] },
  { id: 'inv-spell', topic: 'investigate', module: 'incidents', q: 'Why will the investigation not approve / export?', a: 'Spelling and grammar must pass before an investigation can be Approved, Closed or exported. Run the check, fix what it flags, and try again.', k: 'spelling grammar gate approve blocked export blocked cannot approve cannot close pdf' },
  { id: 'inv-pdf', topic: 'investigate', module: 'incidents', q: 'How do I get the investigation PDF?', a: 'In the Workbench, stage 4 (Close It Out), tap "Open Printable Report (PDF)" or "Download PDF" at the top. It opens in a new tab; choose "Save as PDF" in the print dialog.', k: 'investigation pdf report download print export', links: [L.workbench] },
  { id: 'inv-hierarchy', topic: 'investigate', q: 'What is the hierarchy of controls?', a: 'Most effective to least: Elimination (remove the hazard), Substitution (swap for something less hazardous), Engineering (guards, interlocks, isolation), Administrative (procedures, training, signs, permits), PPE. Strong corrective actions sit near the top. "Retrain the employee" alone is the weakest fix there is.', k: 'hierarchy of controls elimination substitution engineering administrative ppe strong corrective action' },
  { id: 'inv-5why', topic: 'investigate', q: 'How do I do a 5-Why?', a: 'Start with the problem statement and ask "why?" again and again until you reach something the organization controls (a system, procedure, design or decision), usually around five times. Each answer must be backed by evidence. Stop at a person\'s mistake and you have found a symptom, not a root cause.', k: '5 why five why root cause analysis how to ask why' },

  // ── Access ───────────────────────────────────────────────────────────────
  { id: 'magic-link', topic: 'access', q: 'How do I sign in to a management page? (SAIL management, corrective actions, dashboards)', a: 'Enter your email and tap "Email me a sign-in link". Open the email on the same phone or computer and tap the link; the page unlocks. No password. You stay signed in on that device.', k: 'sign in link magic link email link management access no password login dashboard', links: [L.sailMgmt] },
  { id: 'no-link', topic: 'access', q: 'I did not get the sign-in email', a: 'Wait a minute and check spam / junk. Make sure you typed your work email exactly. Tap "Use a different email" to try again. Still nothing? Your email may not be on the access list: contact SLP Alaska.', k: 'did not get email no email sign in link not received spam junk', links: [L.phone] },
  { id: 'not-on-list', topic: 'access', q: 'It says my address is not on the access list', a: 'You signed in fine, but that email has not been given access to management pages. If you should have access (for example you own SAIL items), ask SLP Alaska to add you. Field forms never need this access.', k: 'not on access list unauthorized not authorized access denied no access permission' },
  { id: 'sign-out', topic: 'access', q: 'How do I sign out?', a: 'Management pages have a Sign out button. In the LMS use the sign-out option on the dashboard. On a shared phone or computer, always sign out when you are done.', k: 'sign out log out logout shared device' },
  { id: 'da-tile', topic: 'access', module: 'da-testing', q: 'Where is the Drug & Alcohol testing console?', a: 'The D&A tile only shows for the authorized D&A administrators after they sign in. Everyone else does not see it. That is on purpose. Questions about a test go to your company DER or SLP Alaska.', k: 'drug alcohol d&a testing console random test clearinghouse der where', links: [L.phone] },
  { id: 'client-export', topic: 'access', module: 'client-export', q: 'How do clients download their data?', a: 'Clients use the Client Data Export Portal with the company code and password SLP Alaska issued. They see their own company\'s data only.', k: 'client download data export company code client login', links: [['Client Data Export Portal', '/client-export']] },

  // ── Troubleshooting ──────────────────────────────────────────────────────
  { id: 'not-found', topic: 'trouble', q: 'A page says "Not found"', a: 'Either the link is old, or that part of the portal is switched off for this deployment. Go back to the home page and use the search. If something you need is missing, tell SLP Alaska.', k: 'not found 404 page missing broken link disappeared gone', links: [L.home] },
  { id: 'blank', topic: 'trouble', q: 'The page is blank or will not load', a: 'Pull down to refresh. Check your signal. Close the tab and open portal.slpalaska.com again. Update your browser. Still blank? Try another browser (Chrome or Safari) and tell SLP Alaska which page and phone.', k: 'blank page white screen will not load not loading frozen crash spinning error', links: [L.phone] },
  { id: 'error-msg', topic: 'trouble', q: 'I got an error when I submitted', a: 'Read the message. If it names a missing answer, fix that and submit again. If it is a technical error, do not close the page: wait a moment and tap Submit once more. SafeSubmit forms keep a backup copy and alert SLP automatically. If it keeps failing, screenshot the error and send it to SLP Alaska.', k: 'error submitting error message failed submit went wrong something went wrong' },
  { id: 'popup', topic: 'trouble', q: 'Print or PDF does nothing', a: 'Your browser is probably blocking pop-ups. Allow pop-ups for portal.slpalaska.com and tap Print again.', k: 'popup pop-up blocked print not working pdf not opening allow pop ups' },
  { id: 'gps', topic: 'trouble', q: 'GPS / location will not work on the form', a: 'Allow location access for your browser when asked (Settings → your browser → Location). GPS works better outside. You can still type the location.', k: 'gps location not working geolocation permission coordinates' },
  { id: 'contact', topic: 'trouble', q: 'How do I contact SLP Alaska for help?', a: 'Call SLP Alaska at ' + SLP_PHONE + '. For anything urgent on the job, your supervisor first.', k: 'contact phone number call support help person talk to someone brian slp', links: [L.phone] },
  { id: 'feedback', topic: 'trouble', q: 'I have an idea to make a form better', a: 'Good. Field ideas make the best forms. Tell your supervisor or call SLP Alaska at ' + SLP_PHONE + ' with the form name and your idea.', k: 'idea suggestion feedback improve form change form request feature', links: [L.phone] },

  // ── Safety know-how ──────────────────────────────────────────────────────
  { id: 'leading', topic: 'concepts', q: 'What are leading indicators and why do my BBS cards matter?', a: 'Lagging indicators count harm after it happens (injuries, recordables). Leading indicators measure what we do before it happens: BBS observations, near misses, stop cards, Take 5s, THAs, inspections, overdue actions, training.\n\nYour cards are the data that shows where the next injury is coming from, in time to stop it.', k: 'leading indicators lagging indicators predictive why bbs matters data metrics' },
  { id: 'stky', topic: 'concepts', q: 'What does STKY mean on the BBS card?', a: 'STKY = "Stuff That Kills You": a hazard with the potential for a serious injury or fatality (SIF). Flag it whenever the at-risk behavior could have killed or seriously hurt someone, even if nothing happened.', k: 'stky stuff that kills you sif serious injury fatality potential bbs meaning' },
  { id: 'line-of-fire', topic: 'concepts', q: 'What is "line of fire"?', a: 'Being in the path of moving or released energy: a suspended load, a swinging boom, a pressurized line, a backing vehicle, a pinch point, a falling object. Ask: "If this moves or lets go, where does it go, and am I there?"', k: 'line of fire meaning pinch point struck by caught between' },
  { id: 'lsr', topic: 'concepts', q: 'What are the Lifesaving Rules?', a: 'Short, non-negotiable rules for the activities that kill people: confined space, driving, energy isolation, working at height, lifting operations, line of fire and work permits. The LSR audits check they are followed.', k: 'lifesaving rules lsr life saving rules what are', links: [['LSR-Work Permits Audit', '/lsr-work-permits-audit']] },
  { id: 'energy', topic: 'concepts', q: 'What "energy" does Stop & Take 5 ask about?', a: 'Anything that can hurt you when released: gravity (falls, dropped objects), motion (vehicles, equipment), mechanical, electrical, pressure, temperature (hot / cold), chemical, biological, radiation, sound. Name the energy, then name the control that stops it reaching you.', k: 'energy types energy wheel gravity pressure electrical stop take 5 hazard energy' },
  { id: 'risk-matrix', topic: 'concepts', q: 'How does severity x probability work?', a: 'Severity = how bad it could be. Probability = how likely. Together they give the risk level. High risk means stop and add controls before starting; never accept a high-severity risk because "it\'s unlikely".', k: 'risk matrix severity probability likelihood risk level rating high medium low' },
  { id: 'phases', topic: 'concepts', q: 'What are the weather phase conditions?', a: 'The ASH Book phase conditions restrict travel and outdoor work as wind chill, visibility and temperature get worse. Check the Weather Globe & ASH Book Phases page and the ASH Book before outdoor work or travel.', k: 'phase conditions phase 1 phase 2 phase 3 weather restrictions travel ban', links: [L.weather, L.ash] },
  { id: 'moc-when', topic: 'concepts', module: 'moc', q: 'When do I need a Management of Change?', a: 'Before any change that could bring in new hazards: new equipment, a changed procedure, a different chemical, a change in staffing or roles, temporary bypasses. Submit the MOC and get it reviewed before the change happens.', k: 'moc when needed management of change required', links: [L.moc] },
  { id: 'safety-meeting-vs', topic: 'concepts', q: 'Safety Meeting vs Toolbox Meeting Assessment: which one?', a: 'Safety Meeting records the meeting itself: topic, discussion, attendees. Toolbox Meeting Quality Assessment is a score of how good a meeting was, filled out by an observer. Hold the meeting → Safety Meeting. Grade the meeting → Toolbox Assessment.', k: 'safety meeting toolbox difference which one attendance', links: [L.safetyMeeting, L.toolbox] },
  { id: 'journey-when', topic: 'concepts', q: 'When do I need a Journey Management Plan?', a: 'Before remote or long-distance travel, especially on the Haul Road, in winter, at night, or anywhere without cell coverage. Plan the route, check-in times, emergency gear and sat phone, and make sure someone is watching for your check-in.', k: 'journey management when needed travel haul road trip driving plan', links: [L.journey] },
  { id: 'drops-calc', topic: 'concepts', q: 'How big should the dropped object exclusion zone be?', a: 'Use the Dropped Object Energy Assessment: enter the object\'s weight and drop height, and it calculates the impact energy, consequence level and an exclusion zone distance.', k: 'exclusion zone dropped object how big distance drop zone barricade', links: [L.drops] },

  // ── Admins & managers ────────────────────────────────────────────────────
  { id: 'dashboards', topic: 'admin', module: 'analytics', q: 'Where is the Predictive Safety Dashboard (leading indicators, risk, overdue items)?', a: 'Home page → Predictive Safety Analytics™ folder → Predictive Safety Dashboard. It opens slp-safety-dashboard.vercel.app in a new tab. Sign in there with your company\'s dashboard login (ask SLP Alaska if your company does not have one). It shows BBS, near misses, Stop & Take 5, THAs, hazards, inspections, open and overdue SAIL items, training and the predictive risk score.\n\nThe other tools in that folder (Investigation Analytics, Similar Incident Finder, Quality Score, Action Calendar, Notification Center) use the emailed sign-in link.', k: 'predictive safety dashboard analytics leading indicators risk score metrics kpi charts trends overdue company dashboard login psa', links: [['Predictive Safety Dashboard', 'https://slp-safety-dashboard.vercel.app'], ['Investigation Analytics', '/investigation-analytics']] },
  { id: 'module-off', topic: 'admin', q: 'How are parts of the portal turned on or off?', a: 'Each part of the portal is a module with an on/off switch (set by SLP Alaska per deployment). A module that is off disappears from the home page and its pages say Not found. Turning it back on brings everything back; no data is lost.', k: 'turn off module toggle switch disable enable hide part of portal' },
  { id: 'weekly-report', topic: 'admin', q: 'What are the weekly report emails?', a: 'Client contacts receive a weekly summary of their company\'s safety activity from the portal. Ask SLP Alaska to change who receives it.', k: 'weekly report email summary client report monday email' },
]
